svg.script:
(function(){
"use strict";
const base=new URL("./",window.location.href).href;
const page="<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover">
<base href="__DOC_BASE__">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
<title>Doc</title>
<link id="tab-cloak-icon" rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%230088a8'/%3E%3Ctext x='32' y='44' font-size='42' text-anchor='middle' fill='white' font-family='Arial'%3ED%3C/text%3E%3C/svg%3E">
<style>
:root {
  --bg-dark: #061d25;
  --panel-bg: rgba(5, 39, 49, 0.78);
  --panel-border: rgba(157, 226, 224, 0.22);
  --text-main: #f2fbf9;
  --text-muted: #a5c8c7;
  --accent: #43c6bd;
  --accent-glow: rgba(67, 198, 189, 0.35);
  --radius-lg: 20px;
  --radius-md: 12px;
  --radius-sm: 8px;
  --font-display: "SF Pro Display", -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
  --font-body: "SF Pro", "SF Pro Text", -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; -webkit-tap-highlight-color: transparent; }
html, body {
  height: 100%;
  height: 100dvh;
  overflow: hidden;
  background: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-body);
}

/* Background Slideshow with 5px Blur; photos stay undimmed */
#bg-container {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
}

.bg-slide {
  position: absolute;
  inset: -30px;
  background-size: cover;
  background-position: center;
  opacity: 0;
  filter: blur(5px);
  -webkit-filter: blur(5px);
  transition: opacity 2.2s cubic-bezier(0.4, 0, 0.2, 1), transform 12s cubic-bezier(0.25, 1, 0.5, 1);
  transform: scale(1);
}

.bg-slide.active {
  opacity: 1;
  transform: scale(1.06);
}

#bg-overlay {
  position: absolute;
  inset: 0;
  z-index: 1;
  background: transparent;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

/* App Shell */
#app {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  height: 100%;
  padding: calc(10px + env(safe-area-inset-top, 0px)) 12px calc(70px + env(safe-area-inset-bottom, 0px));
  max-width: 1200px;
  margin: 0 auto;
}

header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 4px;
  margin-bottom: auto;
}

.brand {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 700;
  letter-spacing: -0.5px;
}

.brand span { color: var(--accent); }

/* Views Container */
.view-panel {
  position: absolute;
  inset: 65px 12px 75px 12px;
  display: none;
  flex-direction: column;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 16px;
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-lg);
  backdrop-filter: blur(14px);
  box-shadow: 0 20px 50px rgba(0,0,0,0.6);
}
.view-panel.active { display: flex; }

#view-home {
  background: none;
  border: none;
  box-shadow: none;
  backdrop-filter: none;
  align-items: center;
  justify-content: center;
}

.home-hero {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  max-width: 600px;
  width: 100%;
  margin-bottom: 60px;
  padding: 0 10px;
}

.home-title {
  font-family: var(--font-display);
  font-size: 38px;
  font-weight: 700;
  margin-bottom: 4px;
  letter-spacing: -1px;
}

.home-subtitle {
  font-size: 13px;
  color: var(--text-muted);
  margin-bottom: 24px;
}

/* Search Bar & Small Dropdown */
.search-container {
  display: flex;
  gap: 6px;
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-lg);
  padding: 6px;
  width: 100%;
  box-shadow: 0 16px 40px rgba(0,0,0,0.5);
  position: relative;
  backdrop-filter: blur(12px);
}

.engine-select { position: relative; }

.engine-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 0;
  color: var(--text-main);
  padding: 10px 12px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
  font-weight: 500;
  min-height: 40px;
}

.engine-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  width: 160px;
  background: #10141D;
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-sm);
  padding: 4px;
  display: none;
  flex-direction: column;
  gap: 2px;
  z-index: 100;
  box-shadow: 0 10px 25px rgba(0,0,0,0.6);
}

.engine-dropdown.open { display: flex; }

.engine-opt {
  background: none;
  border: 0;
  color: var(--text-main);
  padding: 10px;
  border-radius: 6px;
  text-align: left;
  cursor: pointer;
  font-size: 13px;
}

.engine-opt:hover { background: rgba(255, 255, 255, 0.08); }

.search-input {
  flex: 1;
  background: none;
  border: 0;
  outline: 0;
  color: var(--text-main);
  font-size: 16px;
  padding: 0 8px;
  font-family: var(--font-body);
  min-height: 40px;
}

.search-input::placeholder { color: var(--text-muted); }

/* Grid & Cards for Apps/Games */
.section-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-muted);
  margin-bottom: 12px;
  text-transform: uppercase;
  letter-spacing: 0.6px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(110px, 1fr));
  gap: 10px;
  margin-bottom: 24px;
}

.card {
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  padding: 14px 10px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  cursor: pointer;
  touch-action: manipulation;
  transition: background 0.2s, border-color 0.2s;
}

.card:active { background: rgba(255, 255, 255, 0.1); }

.card-icon {
  width: 38px;
  height: 38px;
  border-radius: var(--radius-sm);
  background: rgba(0, 136, 168, 0.15);
  color: var(--accent);
  display: grid;
  place-items: center;
  font-size: 16px;
  font-weight: 700;
}

.card-name {
  font-size: 12px;
  font-weight: 500;
  text-align: center;
}

/* Settings Rows */
.setting-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.setting-row label { font-size: 13px; font-weight: 500; }
.setting-row select, .setting-row input[type="text"] {
  background: rgba(0,0,0,0.4);
  border: 1px solid var(--panel-border);
  color: var(--text-main);
  padding: 6px 10px;
  border-radius: var(--radius-sm);
  outline: 0;
  font-size: 13px;
}

/* Pro Browsing View */
#main-view {
  position: absolute;
  inset: 0;
  z-index: 5;
  background: var(--bg-dark);
  display: none;
  flex-direction: column;
}
#main-view.active { display: flex; }

#browser-frame {
  flex: 1;
  width: 100%;
  height: 100%;
  border: 0;
  background: #fff;
}

/* Collapsible Right-Hand Control Bar */
#right-sidebar {
  position: absolute;
  top: 12px;
  right: 12px;
  z-index: 20;
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  padding: 6px;
  border-radius: var(--radius-md);
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px rgba(0,0,0,0.5);
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
#right-sidebar.collapsed { transform: translateX(calc(100% + 20px)); }

.sidebar-btn {
  background: rgba(255, 255, 255, 0.06);
  border: 0;
  color: var(--text-main);
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  display: grid;
  place-items: center;
  touch-action: manipulation;
}
.sidebar-btn:active { background: var(--accent); color: #fff; }
.sidebar-btn svg { width: 18px; height: 18px; fill: currentColor; }

/* Floating URL Toolbar with Pull-Out Arrow */
#url-toolbar {
  position: absolute;
  bottom: calc(16px + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  padding: 6px 10px;
  border-radius: 99px;
  backdrop-filter: blur(12px);
  box-shadow: 0 10px 30px rgba(0,0,0,0.6);
  max-width: 92vw;
  transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
#url-toolbar.collapsed { opacity: 0; transform: translateX(-50%) translateY(120px); pointer-events: none; }

.toolbar-btn { background: none; border: 0; color: var(--text-main); padding: 8px; cursor: pointer; display: grid; place-items: center; touch-action: manipulation; }
.toolbar-btn svg { width: 16px; height: 16px; fill: currentColor; }
.url-display { font-size: 12px; color: var(--text-muted); max-width: 180px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; padding: 0 4px; }

@media (min-width: 600px) {
  .url-display { max-width: 320px; }
}

/* Floating Panels */
.floating-panel {
  position: absolute;
  top: 50px;
  right: 12px;
  left: 12px;
  max-width: 420px;
  margin-left: auto;
  height: 450px;
  background: var(--panel-bg);
  border: 1px solid var(--panel-border);
  border-radius: var(--radius-lg);
  backdrop-filter: blur(16px);
  z-index: 30;
  display: none;
  flex-direction: column;
  box-shadow: 0 20px 50px rgba(0,0,0,0.7);
  overflow: hidden;
}
.floating-panel.open { display: flex; }
.panel-header { padding: 12px 16px; border-bottom: 1px solid var(--panel-border); display: flex; justify-content: space-between; align-items: center; font-weight: 600; font-size: 13px; }
.panel-close { background: none; border: 0; color: var(--text-muted); cursor: pointer; font-size: 18px; padding: 4px; }
.panel-body { flex: 1; padding: 14px; overflow-y: auto; -webkit-overflow-scrolling: touch; font-size: 12px; }

/* Persistent home taskbar; softly fades while a browser session is active. */
#dock {
  position: fixed !important;
  left: 50% !important;
  bottom: calc(12px + env(safe-area-inset-bottom, 0px)) !important;
  z-index: 2147483000 !important;
  display: flex !important;
  gap: 3px;
  padding: 5px;
  background: rgba(14, 18, 26, 0.88);
  border: 1px solid var(--panel-border);
  border-radius: 99px;
  backdrop-filter: blur(14px);
  box-shadow: 0 12px 35px rgba(0,0,0,0.6);
  transform: translate3d(-50%, 0, 0) !important;
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transition: opacity .3s ease, background .3s ease;
}
/* Hard state switch: the home taskbar and its edge sensor do not exist visually while browsing. */
body.browsing #dock,
body.browsing #dock-edge-trigger {
  display: none !important;
}

.dock-item {
  background: none;
  border: 0;
  color: var(--text-muted);
  padding: 8px 14px;
  border-radius: 99px;
  cursor: pointer;
  font-size: 12px;
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 5px;
  touch-action: manipulation;
  transition: color 0.2s, background 0.2s;
}
.dock-item:active, .dock-item.active { color: var(--text-main); background: rgba(255,255,255,0.08); }
.dock-item svg { width: 16px; height: 16px; fill: currentColor; }

@media (max-width: 480px) {
  .dock-item span { display: none; }
  .dock-item { padding: 10px 14px; }
}

.catalog-head{display:grid;grid-template-columns:minmax(0,1fr) minmax(160px,260px) 145px;gap:9px;align-items:center;margin-bottom:16px}
.catalog-heading{min-width:0}.catalog-heading .section-title{margin:0 0 5px}.catalog-subtitle{font-size:12px;color:var(--text-muted)}
.catalog-search,.catalog-category{width:100%;min-width:0;background:rgba(0,0,0,.34);border:1px solid var(--panel-border);color:var(--text-main);border-radius:11px;padding:11px 12px;outline:0;font:inherit;font-size:13px}
.catalog-search:focus,.catalog-category:focus{border-color:rgba(0,190,220,.65);box-shadow:0 0 0 3px rgba(0,160,190,.12)}
.catalog-grid{grid-template-columns:repeat(auto-fill,minmax(185px,1fr));gap:11px}
.catalog-card{min-height:100px;display:grid;grid-template-columns:44px minmax(0,1fr) 18px;align-items:center;gap:11px;text-align:left;padding:14px;border:1px solid rgba(148,220,211,.18);background:linear-gradient(145deg,rgba(255,255,255,.075),rgba(255,255,255,.025));border-radius:16px;transition:transform .18s,border-color .18s,background .18s;overflow:hidden}
.catalog-card:hover{transform:translateY(-2px);border-color:rgba(92,224,207,.58);background:linear-gradient(145deg,rgba(44,164,153,.22),rgba(255,255,255,.035))}
.catalog-card:active{transform:scale(.985)}.catalog-icon{position:relative;width:44px;height:44px;border-radius:13px;display:grid;place-items:center;background:rgba(255,255,255,.09);border:1px solid rgba(255,255,255,.09);overflow:hidden}
.catalog-icon img{position:absolute;width:27px;height:27px;object-fit:contain}.catalog-icon b{font-size:17px;color:#fff}
.catalog-copy{min-width:0;display:flex;flex-direction:column;gap:5px}.catalog-name{font-size:13px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.catalog-desc{font-size:11px;color:var(--text-muted);line-height:1.35;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.catalog-tag{font-size:9px;letter-spacing:.35px;text-transform:uppercase;color:#9de9df;background:rgba(67,198,189,.13);border:1px solid rgba(67,198,189,.25);border-radius:99px;padding:3px 6px}
.catalog-arrow{color:var(--text-muted);font-size:17px}.catalog-empty{grid-column:1/-1;padding:30px 12px;text-align:center;color:var(--text-muted);font-size:13px;border:1px dashed var(--panel-border);border-radius:14px}
@media(max-width:680px){.catalog-head{grid-template-columns:1fr 1fr}.catalog-heading{grid-column:1/-1}.catalog-grid{grid-template-columns:repeat(auto-fill,minmax(145px,1fr))}.catalog-card{grid-template-columns:38px minmax(0,1fr);padding:11px;gap:9px;min-height:92px}.catalog-icon{width:38px;height:38px}.catalog-icon img{width:23px;height:23px}.catalog-arrow{display:none}}
@media(max-width:390px){.catalog-head{grid-template-columns:1fr}.catalog-heading{grid-column:auto}.catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.catalog-card{grid-template-columns:32px minmax(0,1fr);gap:7px;padding:9px}.catalog-icon{width:32px;height:32px;border-radius:10px}.catalog-icon img{width:20px;height:20px}.catalog-name{font-size:12px}.catalog-desc{font-size:10px}}


/* Waterfront motion system */
#bg-container{position:fixed;inset:0;z-index:0;display:block!important;visibility:visible!important;opacity:1!important}
#bg-container .bg-slide{display:block!important;visibility:visible!important}
#app{background:transparent}

:root{--ease-water:cubic-bezier(.2,.75,.25,1)}
body{background:radial-gradient(ellipse at 15% 15%,rgba(24,126,133,.28),transparent 42%),linear-gradient(145deg,#061d25,#092f3b 58%,#071f2a)}
#bg-overlay{background:linear-gradient(145deg,rgba(3,30,39,.16),rgba(3,27,37,.08))}
.brand,.home-title{ text-shadow:0 8px 35px rgba(0,0,0,.22)}
.home-subtitle{color:var(--text-main);font-weight:600;text-shadow:0 2px 14px rgba(0,0,0,.42);transition:opacity .26s ease,transform .26s var(--ease-water);min-height:20px}
.home-subtitle.splash-out{opacity:0;transform:translateY(7px)}
.view-panel.active{animation:view-rise .48s var(--ease-water) both}
@keyframes view-rise{from{opacity:0;transform:translateY(14px) scale(.99)}to{opacity:1;transform:translateY(0) scale(1)}}
.catalog-card{position:relative;isolation:isolate;animation:card-arrive .55s var(--ease-water) both}
.catalog-card:before{content:"";position:absolute;inset:0;z-index:-1;opacity:0;background:radial-gradient(circle at 10% 0%,rgba(93,224,207,.18),transparent 65%);transition:opacity .3s ease}
.catalog-card:hover:before{opacity:1}
.catalog-icon{background:linear-gradient(145deg,rgba(255,255,255,.13),rgba(255,255,255,.035));border-color:rgba(170,235,225,.18)}
.catalog-icon img{width:29px;height:29px;object-fit:contain;filter:drop-shadow(0 2px 5px rgba(0,0,0,.18))}
.catalog-arrow svg{width:17px;height:17px}
@keyframes card-arrive{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
.search-container,.engine-btn,.catalog-search,.catalog-category,.setting-row select,.setting-row input{transition:border-color .25s,box-shadow .25s,background .25s,transform .25s}
.search-container:focus-within{border-color:rgba(105,224,211,.55);box-shadow:0 18px 48px rgba(0,0,0,.35),0 0 0 4px rgba(67,198,189,.1)}
#right-sidebar{background:rgba(5,44,53,.82);border-color:rgba(157,226,224,.25)}
#main-view{background:#061d25;animation:browser-enter .35s var(--ease-water) both}
@keyframes browser-enter{from{opacity:.7}to{opacity:1}}
.sidebar-btn{background:rgba(67,198,189,.13);border:1px solid rgba(157,226,224,.18);transition:transform .2s,background .2s}
.sidebar-btn:hover{transform:scale(1.06);background:rgba(67,198,189,.25)}
#url-toolbar{background:rgba(5,39,49,.9);border-color:rgba(157,226,224,.25)}
#url-toolbar.collapsed{visibility:hidden}
button:focus-visible,input:focus-visible,select:focus-visible{outline:2px solid #78ded2;outline-offset:3px}
@media(max-width:680px){
 #app{padding:calc(8px + env(safe-area-inset-top,0px)) 10px calc(74px + env(safe-area-inset-bottom,0px))}
 header{margin-bottom:20px}
 .view-panel{inset:58px 8px calc(76px + env(safe-area-inset-bottom,0px)) 8px;padding:13px;border-radius:18px}
 .home-title{font-size:clamp(32px,9vw,42px)}
 .home-hero{margin-bottom:24px}
 #main-view{padding-top:env(safe-area-inset-top,0px)}
 #right-sidebar{top:calc(8px + env(safe-area-inset-top,0px));right:8px}
 #url-toolbar{bottom:calc(8px + env(safe-area-inset-bottom,0px));max-width:calc(100vw - 20px)}
 .url-display{max-width:32vw}
 .toolbar-btn{padding:9px}
 .catalog-head{gap:8px}
}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

/* Remastered browser chrome */
#main-view{isolation:isolate}
#browser-tabs{position:relative;z-index:1;width:100%;height:39px;min-height:39px;display:flex;align-items:center;gap:8px;padding:0 2px 6px;border-bottom:1px solid rgba(157,226,224,.14)}
#tab-strip{display:flex;align-items:center;gap:6px;min-width:0;flex:1;height:100%;overflow-x:auto;scrollbar-width:none}
#tab-strip::-webkit-scrollbar{display:none}
.browser-tab{position:relative;display:flex;align-items:center;gap:9px;min-width:125px;max-width:225px;height:38px;padding:0 11px;border:1px solid transparent;border-radius:11px;background:rgba(255,255,255,.045);color:var(--text-muted);font-size:12px;cursor:default;user-select:none;flex:0 1 190px;touch-action:pan-y;transition:background .18s,border-color .18s,opacity .16s}
.browser-tab.active{background:rgba(67,198,189,.16);border-color:rgba(110,221,210,.3);color:var(--text-main)}
.browser-tab.tab-drag-source{visibility:hidden}
.tab-drop-placeholder{height:34px;min-width:38px;max-width:225px;flex:0 1 190px;border:1px solid rgba(120,220,211,.7);border-radius:10px;background:rgba(67,198,189,.12);box-shadow:inset 0 0 0 1px rgba(120,220,211,.08);pointer-events:none;transition:width .18s ease}
.browser-tab.tab-drag-ghost{visibility:visible!important}
.tab-drag-ghost{position:fixed!important;z-index:2147483647!important;pointer-events:none!important;opacity:1!important;background:rgba(8,53,62,.98)!important;border-color:rgba(120,220,211,.7)!important;box-shadow:0 12px 30px rgba(0,0,0,.34),0 0 0 1px rgba(120,220,211,.13)!important;transition:none!important;cursor:grabbing!important}
#tab-strip.is-reordering .browser-tab:not(.tab-drag-source){transition:transform .2s cubic-bezier(.2,.8,.2,1),background .18s,border-color .18s}
#tab-strip.is-reordering{overflow-x:auto;overflow-y:visible}
.browser-tab .tab-title{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;text-align:left}
.browser-tab .tab-close{border:0;background:none;color:inherit;opacity:.6;font-size:16px;line-height:1;cursor:pointer;padding:2px 3px}
.browser-tab .tab-close:hover{opacity:1;color:#ff9a9a}
#tab-strip.is-reordering{overflow-x:auto;scroll-behavior:auto}
#tab-strip.is-reordering .browser-tab{transition:width .16s ease,flex-basis .16s ease}
.chrome-icon-btn{width:37px;height:37px;flex:0 0 37px;border:1px solid transparent;border-radius:11px;background:transparent;color:#d9efec;display:grid;place-items:center;cursor:pointer;transition:background .2s,border-color .2s,transform .2s}
.chrome-icon-btn svg{width:19px;height:19px}
.chrome-icon-btn:hover{background:rgba(255,255,255,.09);border-color:rgba(157,226,224,.18)}
.chrome-icon-btn:active{transform:scale(.92)}
#new-tab{background:rgba(255,255,255,.055);border-color:rgba(157,226,224,.14)}
#browser-frame{position:absolute;inset:0;width:100%;height:100%}
#browser-chrome{position:absolute;z-index:50;left:50%;bottom:18px;transform:translate(-50%,0);width:min(760px,calc(100vw - 28px));min-height:0;display:flex;flex-direction:column;align-items:stretch;gap:5px;padding:8px 10px;background:rgba(5,34,43,.91);border:1px solid rgba(157,226,224,.28);border-radius:19px;box-shadow:0 16px 55px rgba(0,0,0,.48),inset 0 1px rgba(255,255,255,.08);backdrop-filter:blur(26px) saturate(145%);-webkit-backdrop-filter:blur(26px) saturate(145%);transition:transform .42s cubic-bezier(.2,.8,.2,1),opacity .28s}
#browser-chrome.collapsed{transform:translate(-50%,145%);opacity:0;pointer-events:none}
#browser-chrome-controls{width:100%;min-width:0;display:flex;align-items:center;gap:5px}
.chrome-divider{width:1px;height:25px;background:rgba(157,226,224,.18);margin:0 3px;flex:0 0 1px}
.chrome-url-shell{height:40px;min-width:0;flex:1;display:flex;align-items:center;gap:9px;padding:0 12px;border-radius:12px;background:rgba(0,0,0,.2);border:1px solid rgba(157,226,224,.12)}
.chrome-url-shell .url-lock{display:grid;place-items:center;color:#75cfc5}
.url-lock svg{width:14px;height:14px}
.chrome-url-shell .url-display{max-width:none;min-width:0;flex:1;width:100%;color:#d6e9e7;text-align:left;background:transparent;border:0;outline:0;font:12px var(--font-body);padding:0}
.chrome-collapse{margin-left:1px}
#chrome-reveal{position:absolute;z-index:51;bottom:7px;left:50%;transform:translate(-50%,20px);opacity:0;pointer-events:none;width:43px;height:25px;border:1px solid rgba(157,226,224,.25);border-bottom:0;border-radius:12px 12px 0 0;background:rgba(5,34,43,.94);color:#dffbf5;display:grid;place-items:center;transition:transform .3s,opacity .25s;cursor:pointer}
#chrome-reveal svg{width:17px;height:17px}
#chrome-reveal.visible{transform:translate(-50%,0);opacity:1;pointer-events:auto}
#browser-menu-popover{position:absolute;z-index:70;left:max(12px,calc(50% - 345px));bottom:88px;width:205px;padding:6px;background:rgba(5,34,43,.97);border:1px solid rgba(157,226,224,.23);border-radius:15px;box-shadow:0 18px 50px rgba(0,0,0,.5);backdrop-filter:blur(22px);opacity:0;transform:translateY(8px) scale(.98);pointer-events:none;transition:.2s}
#browser-menu-popover.open{opacity:1;transform:translateY(0) scale(1);pointer-events:auto}
#browser-menu-popover button{width:100%;display:flex;align-items:center;gap:11px;padding:11px;border:0;border-radius:9px;background:none;color:var(--text-main);font:500 12px var(--font-body);text-align:left;cursor:pointer}
#browser-menu-popover button:hover{background:rgba(255,255,255,.08)}
#browser-menu-popover svg{width:17px;height:17px;color:#8ddbd2}
.floating-panel{top:76px;left:18px;right:auto;width:min(390px,calc(100vw - 36px));height:min(460px,calc(100vh - 115px));max-width:none;margin:0;border-color:rgba(157,226,224,.26);background:rgba(5,34,43,.94);backdrop-filter:blur(25px) saturate(145%);border-radius:17px;touch-action:pan-y}
.floating-panel.open{animation:panel-float-in .22s cubic-bezier(.2,.8,.2,1) both}
@keyframes panel-float-in{from{opacity:0;transform:translateY(9px) scale(.985)}to{opacity:1;transform:translateY(0) scale(1)}}
.panel-header.drag-handle{cursor:grab;user-select:none;touch-action:none}
.panel-header.drag-handle:active{cursor:grabbing}
.panel-close{font-size:21px}
#main-view .panel-body{font-size:12px}
.history-entry,.bookmark-entry{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 9px;border-bottom:1px solid rgba(157,226,224,.1);border-radius:8px;cursor:pointer}
.history-entry:hover,.bookmark-entry:hover{background:rgba(255,255,255,.06)}
.history-entry strong,.bookmark-entry strong{display:block;font-size:12px;font-weight:550;color:#e8f7f4}
.history-entry small,.bookmark-entry small{display:block;margin-top:4px;color:var(--text-muted);font-size:10px;overflow-wrap:anywhere}
.history-empty{padding:22px 10px;color:var(--text-muted);text-align:center}
@media(max-width:600px){#browser-tabs{height:35px;min-height:35px;padding:0 1px 5px}.browser-tab{min-width:105px;max-width:155px;flex-basis:130px}.chrome-icon-btn{width:34px;height:34px;flex-basis:34px}#browser-chrome{bottom:calc(10px + env(safe-area-inset-bottom,0px));gap:3px;padding:6px;width:calc(100vw - 16px);border-radius:16px}#browser-chrome-controls{gap:2px}.chrome-url-shell{padding:0 8px;gap:6px}.chrome-divider{margin:0 1px}.floating-panel{top:60px;left:8px;width:calc(100vw - 16px);height:min(420px,calc(100dvh - 85px))}#browser-menu-popover{left:8px;bottom:76px}}
body.browsing .view-panel{visibility:hidden}


/* App and Play library — matching the waterfront browser chrome */
.catalog-view{gap:0!important}
.catalog-hero{position:relative;flex:0 0 auto;padding:clamp(18px,3vw,30px);margin:-2px -2px 20px;border:1px solid rgba(157,226,224,.18);border-radius:22px;overflow:hidden;background:linear-gradient(115deg,rgba(9,66,75,.82),rgba(7,40,52,.66) 55%,rgba(6,31,42,.72));box-shadow:0 16px 42px rgba(0,0,0,.18)}
.catalog-hero:after{content:"";position:absolute;width:260px;height:260px;right:-70px;top:-150px;border-radius:50%;background:radial-gradient(circle,rgba(82,220,204,.2),transparent 68%);pointer-events:none}
.play-hero{background:linear-gradient(115deg,rgba(8,62,69,.88),rgba(13,47,64,.76) 55%,rgba(17,37,56,.78))}
.catalog-kicker{display:flex;align-items:center;gap:8px;font-size:9px;letter-spacing:1.45px;font-weight:750;color:#a7d8d2;margin-bottom:13px}

.catalog-title-row{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:20px}
.catalog-title{font-size:clamp(27px,5vw,38px);line-height:1;font-weight:720;letter-spacing:-1.2px;color:#f3fffc}
.catalog-subtitle{font-size:12px;color:#b0ceca;margin-top:8px}
.catalog-count{white-space:nowrap;border:1px solid rgba(164,225,216,.2);background:rgba(255,255,255,.055);border-radius:99px;padding:7px 10px;color:#bce3dc;font-size:10px}
.catalog-controls{display:grid;grid-template-columns:minmax(0,1fr) minmax(145px,190px);gap:9px}
.catalog-search-wrap{display:flex;align-items:center;gap:9px;min-width:0;padding:0 12px;border:1px solid rgba(157,226,224,.2);border-radius:12px;background:rgba(1,19,27,.32);transition:border-color .2s,background .2s,box-shadow .2s}
.catalog-search-wrap:focus-within{border-color:rgba(104,217,201,.65);background:rgba(1,19,27,.48);box-shadow:0 0 0 3px rgba(67,198,189,.1)}
.catalog-search-wrap svg{width:16px;height:16px;flex:0 0 auto;fill:none;stroke:#91c6c0;stroke-width:1.7}
.catalog-search-wrap .catalog-search{height:42px;padding:0;border:0;background:transparent;box-shadow:none!important;font-size:12px}
.catalog-search-wrap .catalog-search:focus{outline:0}
.catalog-category{height:44px;border-radius:12px;background-color:rgba(1,19,27,.42);font-size:11px}
.catalog-section-label{display:flex;justify-content:space-between;align-items:center;margin:0 2px 11px;color:#91b8b4;font-size:9px;letter-spacing:1.15px;font-weight:700}
.catalog-section-label i{font-style:normal;color:#65d4c6;font-size:13px;margin-left:4px}
.catalog-grid{grid-template-columns:repeat(auto-fill,minmax(205px,1fr));gap:10px;margin:0 0 12px}
.catalog-card{position:relative;min-height:92px;display:grid;grid-template-columns:46px minmax(0,1fr) 18px;align-items:center;gap:12px;padding:13px 14px;border:1px solid rgba(160,222,214,.15);border-radius:16px;background:linear-gradient(145deg,rgba(14,67,76,.62),rgba(5,35,47,.62));box-shadow:inset 0 1px rgba(255,255,255,.045),0 8px 22px rgba(0,0,0,.1);text-align:left;animation:library-card-in .42s var(--ease-water) both;animation-delay:calc(var(--card-order)*24ms);transition:transform .2s,border-color .2s,background .2s,box-shadow .2s}
.catalog-card:before{content:"";position:absolute;inset:0;border-radius:inherit;background:radial-gradient(circle at 0% 0%,rgba(94,223,205,.14),transparent 58%);opacity:0;pointer-events:none;transition:opacity .2s}
.catalog-card:hover{transform:translateY(-3px);border-color:rgba(105,224,211,.5);background:linear-gradient(145deg,rgba(17,82,88,.78),rgba(6,42,54,.78));box-shadow:0 13px 28px rgba(0,0,0,.2),0 0 0 1px rgba(93,218,203,.06)}
.catalog-card:hover:before{opacity:1}
.catalog-card:active{transform:scale(.985)}
.catalog-icon{position:relative;z-index:1;width:46px;height:46px;border-radius:14px;background:linear-gradient(145deg,rgba(126,222,210,.16),rgba(255,255,255,.045));border:1px solid rgba(172,236,225,.2);box-shadow:inset 0 1px rgba(255,255,255,.12),0 5px 12px rgba(0,0,0,.12)}
.catalog-icon img{width:27px;height:27px;object-fit:contain;filter:drop-shadow(0 2px 5px rgba(0,0,0,.24))}
.play-card .catalog-icon{border-radius:16px;background:linear-gradient(145deg,rgba(117,193,214,.2),rgba(255,255,255,.045))}
.catalog-copy{position:relative;z-index:1;gap:5px}
.catalog-name{font-size:12px;font-weight:680;letter-spacing:.05px;color:#effbf8}
.catalog-desc{font-size:10px;color:#a8c9c5;line-height:1.35}
.catalog-tag{align-self:flex-start;font-size:8px;letter-spacing:.7px;color:#a9e7dc;background:rgba(67,198,189,.1);border:1px solid rgba(103,215,202,.2);padding:3px 7px}
.catalog-arrow{position:relative;z-index:1;color:#8abbb4;transition:transform .2s,color .2s}
.catalog-card:hover .catalog-arrow{transform:translate(2px,-2px);color:#a3f2e3}
.catalog-empty{grid-column:1/-1;padding:35px 15px;text-align:center;color:#a8c9c5;font-size:12px;border:1px dashed rgba(157,226,224,.24);border-radius:16px;background:rgba(255,255,255,.025)}
@keyframes library-card-in{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:680px){.catalog-hero{padding:18px;margin-bottom:16px;border-radius:18px}.catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.catalog-card{grid-template-columns:38px minmax(0,1fr);gap:9px;padding:10px;min-height:88px}.catalog-icon{width:38px;height:38px;border-radius:12px}.catalog-icon img{width:23px;height:23px}.catalog-arrow{display:none}.catalog-title-row{margin-bottom:16px}}
@media(max-width:390px){.catalog-controls{grid-template-columns:1fr}.catalog-category{width:100%}.catalog-count{font-size:9px;padding:6px 8px}.catalog-card{padding:9px;gap:7px;min-height:84px}.catalog-name{font-size:11px}.catalog-desc{font-size:9px}}


/* Native select menus are replaced with in-page Doc menus */
.catalog-dropdown,.custom-select{position:relative;width:100%;min-width:0}
.catalog-dropdown-trigger,.custom-select-trigger{width:100%;height:44px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:0 13px;border:1px solid rgba(157,226,224,.2);border-radius:12px;background:rgba(1,19,27,.42);color:#d9efeb;font:inherit;font-size:11px;text-align:left;cursor:pointer;transition:border-color .18s,background .18s}
.catalog-dropdown-trigger:hover,.custom-select-trigger:hover,.catalog-dropdown.open .catalog-dropdown-trigger,.custom-select.open .custom-select-trigger{border-color:rgba(104,217,201,.55);background:rgba(1,24,32,.72)}
.catalog-dropdown-trigger svg,.custom-select-trigger svg{width:14px;height:14px;flex:0 0 auto;fill:none;stroke:#9bc9c2;stroke-width:1.8;transition:transform .18s}
.catalog-dropdown.open .catalog-dropdown-trigger svg,.custom-select.open .custom-select-trigger svg{transform:rotate(180deg)}
.catalog-dropdown-menu,.custom-select-menu{position:absolute;z-index:80;top:calc(100% + 7px);right:0;left:0;max-height:240px;overflow:auto;padding:5px;border:1px solid rgba(157,226,224,.22);border-radius:13px;background:rgba(5,28,37,.97);box-shadow:0 16px 38px rgba(0,0,0,.36);backdrop-filter:blur(20px);-webkit-backdrop-filter:blur(20px);opacity:0;transform:translateY(-5px);pointer-events:none;transition:opacity .15s,transform .15s}
.catalog-dropdown.open .catalog-dropdown-menu,.custom-select.open .custom-select-menu{opacity:1;transform:translateY(0);pointer-events:auto}
.catalog-dropdown-option,.custom-select-option{width:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:9px 10px;border:0;border-radius:8px;background:transparent;color:#c5dfda;font:inherit;font-size:11px;text-align:left;cursor:pointer}
.catalog-dropdown-option:hover,.custom-select-option:hover{background:rgba(93,190,178,.13);color:#f2fffc}
.catalog-dropdown-option[aria-selected="true"],.custom-select-option[aria-selected="true"]{background:rgba(93,190,178,.17);color:#a8eee0}
.catalog-dropdown-option[aria-selected="true"]:after,.custom-select-option[aria-selected="true"]:after{content:"✓";color:#9ce5d8}
@media(max-width:390px){.catalog-dropdown-trigger{height:42px}}



/* Minimal Doc loading treatment */
.doc-loader{position:fixed;inset:0;z-index:2147483600;display:grid;place-items:center;padding:24px;background:rgba(4,25,33,.94);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px)}
.doc-loader[hidden]{display:none}
.doc-loader-card{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:19px;padding:0;border:0;background:transparent;box-shadow:none;text-align:center}
.doc-loader-mark{font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;font-size:30px;line-height:1;font-weight:600;letter-spacing:-1.4px;color:#f2fbf9;margin:0}
.doc-loader-mark span{display:none}
.doc-loader-label,.doc-loader-track{display:none!important}
.doc-loader-spinner{width:27px;height:27px;border:2px solid rgba(157,226,224,.2);border-top-color:#9de9df;border-right-color:#43c6bd;border-radius:50%;animation:doc-spin .72s linear infinite}
@keyframes doc-spin{to{transform:rotate(360deg)}}
#startup-loader{z-index:2147483601}
#page-loader{position:absolute;inset:0;z-index:15;background:rgba(4,25,33,.68)}
#page-loader .doc-loader-card{gap:15px}
#page-loader .doc-loader-mark{font-size:25px}
@media(prefers-reduced-motion:reduce){.doc-loader-spinner{animation-duration:1.8s}}


/* Navigation loader: fade over the page, then clear only after the frame responds. */
#page-loader{opacity:0;visibility:hidden;pointer-events:none;transition:opacity .26s ease,visibility 0s linear .26s}
#page-loader.is-visible{opacity:1;visibility:visible;pointer-events:auto;transition-delay:0s}
/* Simple app/play library: keep search and category filtering, remove extra decoration. */
#view-apps .catalog-kicker,#view-games .catalog-kicker,#view-apps .catalog-subtitle,#view-games .catalog-subtitle,#view-apps .catalog-section-label,#view-games .catalog-section-label{display:none}
#view-apps .catalog-hero,#view-games .catalog-hero{padding:18px 18px 14px;margin-bottom:14px;border-radius:16px;background:rgba(5,39,49,.66);box-shadow:none}
#view-apps .catalog-title-row,#view-games .catalog-title-row{align-items:center;margin-bottom:12px}
#view-apps .catalog-title,#view-games .catalog-title{font-size:25px;letter-spacing:-.7px}
#view-apps .catalog-count,#view-games .catalog-count{padding:5px 8px;font-size:10px}
#view-apps .catalog-controls,#view-games .catalog-controls{grid-template-columns:minmax(0,1fr) minmax(125px,155px);gap:8px}
#view-apps .catalog-grid,#view-games .catalog-grid{grid-template-columns:repeat(auto-fill,minmax(175px,1fr));gap:8px}
#view-apps .catalog-card,#view-games .catalog-card{min-height:68px;grid-template-columns:36px minmax(0,1fr);gap:10px;padding:10px 12px;border-radius:12px;box-shadow:none;animation:none;background:rgba(255,255,255,.045)}
#view-apps .catalog-card:before,#view-games .catalog-card:before,#view-apps .catalog-arrow,#view-games .catalog-arrow,#view-apps .catalog-desc,#view-games .catalog-desc{display:none}
#view-apps .catalog-icon,#view-games .catalog-icon{width:36px;height:36px;border-radius:10px}
#view-apps .catalog-icon img,#view-games .catalog-icon img{width:22px;height:22px}
#view-apps .catalog-copy,#view-games .catalog-copy{gap:5px}
#view-apps .catalog-name,#view-games .catalog-name{font-size:12px}
#view-apps .catalog-tag,#view-games .catalog-tag{font-size:8px;padding:2px 5px;width:max-content}
@media(max-width:680px){#view-apps .catalog-controls,#view-games .catalog-controls{grid-template-columns:minmax(0,1fr) 125px}#view-apps .catalog-grid,#view-games .catalog-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}

/* Oversized Doc wordmark. */
.brand{font-size:44px;letter-spacing:-1.8px;line-height:1}
.home-title{font-size:clamp(64px,8vw,88px);letter-spacing:-3px;line-height:.98}
.doc-loader-mark{font-size:58px;letter-spacing:-2.8px;line-height:1}
#page-loader .doc-loader-mark{font-size:50px}
@media(max-width:680px){.brand{font-size:38px}.home-title{font-size:clamp(54px,13vw,72px);letter-spacing:-2.4px}.doc-loader-mark{font-size:50px}}
</style>
</head>
<body>

<div class="doc-loader" id="startup-loader" role="status" aria-live="polite">
  <div class="doc-loader-card"><div class="doc-loader-mark">Doc</div><div class="doc-loader-spinner" aria-hidden="true"></div></div>
</div>
<script>
/* Independent failsafe: the workspace splash must never trap the app if a later script fails. */
(function(){
  var loader=document.getElementById("startup-loader");
  if(!loader)return;
  var dismissed=false;
  function dismiss(){
    if(dismissed||!loader.isConnected)return;
    dismissed=true;
    loader.style.transition="opacity .28s ease,visibility 0s linear .28s";
    loader.style.opacity="0";
    loader.style.visibility="hidden";
    setTimeout(function(){if(loader.isConnected)loader.remove()},320);
  }
  window.addEventListener("error",dismiss,{once:true});
  window.addEventListener("unhandledrejection",dismiss,{once:true});
  setTimeout(dismiss,3200);
})();
</script>

<!-- Your Uploaded Waterfront Photos Background Slideshow -->
<div id="bg-container">
  <div class="bg-slide active" id="slide1"></div>
  <div class="bg-slide" id="slide2"></div>
  <div id="bg-overlay"></div>
</div>

<div id="app">
  <header>
    <div class="brand">Doc<span>.</span></div>
  </header>

  <!-- Home View -->
  <div class="view-panel active" id="view-home">
    <div class="home-hero">
      <h1 class="home-title">Doc.</h1>
      <div class="home-subtitle" id="home-splash">A little tide, a lot of tabs.</div>
      <div class="search-container">
        <div class="engine-select">
          <button class="engine-btn" id="engine-toggle">
            <span id="engine-name">DuckDuckGo</span>
          </button>
          <div class="engine-dropdown" id="engine-menu">
            <button class="engine-opt" data-engine="ddg">DuckDuckGo</button>
            <button class="engine-opt" data-engine="google">Google</button>
            <button class="engine-opt" data-engine="brave">Brave</button>
            <button class="engine-opt" data-engine="bing">Bing</button>
          </div>
        </div>
        <input type="text" class="search-input" id="search-bar" placeholder="Search or URL..." autocomplete="off">
      </div>
    </div>
  </div>

  <!-- App Library -->
  <div class="view-panel catalog-view" id="view-apps">
    <div class="catalog-hero app-hero">
      <div class="catalog-kicker">THE WATERFRONT / LIBRARY</div>
      <div class="catalog-title-row"><div><h2 class="catalog-title">Apps</h2><p class="catalog-subtitle">Your everyday stops, collected in one place.</p></div><span class="catalog-count" id="apps-count">12 destinations</span></div>
      <div class="catalog-controls"><label class="catalog-search-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input class="catalog-search" id="apps-filter" type="search" placeholder="Search your apps" autocomplete="off"></label><div class="catalog-dropdown" id="apps-category" aria-label="Filter apps"></div></div>
    </div>
    <div class="catalog-section-label"><span>YOUR COLLECTION</span><span>OPEN IN DOC <i>↗</i></span></div>
    <div class="grid catalog-grid app-grid" id="apps-grid"></div>
  </div>

  <!-- Play Library -->
  <div class="view-panel catalog-view" id="view-games">
    <div class="catalog-hero play-hero">
      <div class="catalog-kicker">THE WATERFRONT / PLAY</div>
      <div class="catalog-title-row"><div><h2 class="catalog-title">Play</h2><p class="catalog-subtitle">Pick a world. Jump straight in.</p></div><span class="catalog-count" id="games-count">12 experiences</span></div>
      <div class="catalog-controls"><label class="catalog-search-wrap"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 5 5"/></svg><input class="catalog-search" id="games-filter" type="search" placeholder="Find something to play" autocomplete="off"></label><div class="catalog-dropdown" id="games-category" aria-label="Filter play library"></div></div>
    </div>
    <div class="catalog-section-label"><span>READY WHEN YOU ARE</span><span>OPEN IN DOC <i>↗</i></span></div>
    <div class="grid catalog-grid play-grid" id="games-grid"></div>
  </div>

  <!-- Settings View -->
  <div class="view-panel" id="view-settings">
    <div class="section-title">Preferences</div>
    <div class="setting-row">
      <label>Tab Cloak</label>
      <div class="custom-select" id="setting-cloak" aria-label="Tab appearance"></div>
    </div>
    <div class="setting-row">
      <label>Panic Key</label>
      <input type="text" id="setting-panic" value="`" style="width:45px; text-align:center;">
    </div>
