<script>
const DOC_ENGINE=(()=>{
 const base=new URL("./",document.baseURI),wisp="wss://wisp.mercurywork.shop/";
 const paths={sw:new URL("sw.js",base).href,runtime:new URL("scramjet.js",base).href,wasm:new URL("scramjet.wasm",base).href,utils:new URL("scramjet-utils.js",base).href,api:new URL("controller.api.js",base).href,inject:new URL("controller.inject.js",base).href,transport:"https://cdn.jsdelivr.net/gh/theexpie/Splooshi@343bcb5c839963d01ed3addb1487410876943756/libcurl-client.js"};
 let controller=null,utils=null,frame=null,starting=null;
 const log=m=>{const box=document.getElementById("console-logs");if(box){const line=document.createElement("div");line.textContent="> "+m;box.appendChild(line);box.scrollTop=box.scrollHeight;}console.info("[Doc]",m)};
 const load=src=>new Promise((resolve,reject)=>{const s=document.createElement("script");s.src=src;s.async=false;s.onload=resolve;s.onerror=()=>reject(new Error("Failed to load "+src));document.head.appendChild(s)});
 async function waitForServiceWorkerControl(registration){
  const container=navigator.serviceWorker;
  const current=()=>container.controller;
  if(current())return current();
  log("Waiting for service worker control…");
  return new Promise((resolve,reject)=>{
   let settled=false;
   const cleanup=()=>{
    clearTimeout(timer);
    container.removeEventListener("controllerchange",check);
    registration.active?.removeEventListener("statechange",check);
   };
   const finish=worker=>{
    if(settled||!worker)return;
    settled=true;cleanup();resolve(worker);
   };
   const check=()=>finish(current());
   const timer=setTimeout(()=>{
    if(current())return check();
    if(settled)return;
    settled=true;cleanup();
    reject(new Error("Service worker is active but has not taken control of this page. Doc will retry automatically when control changes; no manual refresh is needed."));
   },20000);
   container.addEventListener("controllerchange",check);
   registration.active?.addEventListener("statechange",check);
   // Re-check after listeners are attached so a controllerchange between the
   // initial check and listener registration cannot leave initialization stuck.
   check();
  });
 }
 async function init(){
  if(controller)return controller;if(starting)return starting;
  starting=(async()=>{
   if(!("serviceWorker"in navigator)||!window.isSecureContext)throw new Error("Scramjet needs HTTPS and service-worker support. Open Doc from GitHub Pages.");
   log("Registering Scramjet service worker…");
   await navigator.serviceWorker.register(paths.sw,{scope:base.pathname,updateViaCache:"none"});
   const registration=await navigator.serviceWorker.ready;
   if(!registration.active)throw new Error("Scramjet service worker did not become active.");
   const sw=await waitForServiceWorkerControl(registration);
   if(!sw)throw new Error("Scramjet service worker is active but this page is not controlled. Check that Doc is opened from its GitHub Pages or JSDelivr URL.");
   log("Loading Scramjet runtime and Wisp transport…");
   await load(paths.runtime);await load(paths.api);await load(paths.utils);await load(paths.transport);
   const api=window.$scramjetController;utils=window.$scramjetUtils;
   if(!api?.Controller)throw new Error("Scramjet controller API did not load.");
   if(!utils?.HttpCachePlugin||!utils?.UrlWatcherPlugin||!utils?.CatchEscapedLinksPlugin)throw new Error("Scramjet utility plugins did not load.");
   if(!window.LibcurlTransport?.LibcurlClient)throw new Error("Wisp transport client did not load.");
   api.config.injectPath=paths.inject;api.config.wasmPath=paths.wasm;api.config.scramjetPath=paths.runtime;api.config.prefix=new URL("./~/sj/",base).pathname;
   const transport=new window.LibcurlTransport.LibcurlClient({wisp,websocket:wisp});
   controller=new api.Controller({serviceworker:sw,transport});
   await Promise.race([controller.wait(),new Promise((_,reject)=>setTimeout(()=>reject(new Error("Scramjet handshake timed out. Check the Wisp endpoint and service worker.")),18000))]);
   log("Scramjet is ready.");return controller;
  })().catch(e=>{starting=null;log("ENGINE ERROR: "+(e?.message||e));throw e});
  return starting;
 }
 function attach(iframe){
  if(frame)return frame;if(!controller)throw new Error("Scramjet is not ready.");
  const plugins=[new utils.HttpCachePlugin(),new utils.UrlWatcherPlugin(url=>{if(/^https?:\/\//i.test(String(url||""))){urlDisplay.value=url;document.getElementById("active-tab-title").textContent=(new URL(url)).hostname.replace(/^www\./,"")}}),new utils.CatchEscapedLinksPlugin(url=>{const target=new URL(window.location.href);target.search="";target.searchParams.set("url",url.href);return target})];
  frame=controller.createFrame(iframe,{plugins});return frame;
 }
 async function go(iframe,url){await init();return attach(iframe).go(url)}
 function back(iframe){if(frame?.back)return frame.back();try{iframe.contentWindow.history.back()}catch{}}
 function forward(iframe){if(frame?.forward)return frame.forward();try{iframe.contentWindow.history.forward()}catch{}}
 function reload(iframe){if(frame?.reload)return frame.reload();try{iframe.contentWindow.location.reload()}catch{}}
 return {init,go,back,forward,reload,get ready(){return !!controller}};
})();

