/* Waterfront photo slideshow — use encoded, same-origin paths for GitHub Pages. */
const PHOTOS = [
  "./assets/images/waterfront-01.jpg",
  "./assets/images/waterfront-02.jpg",
  "./assets/images/waterfront-03.jpg",
  "./assets/images/waterfront-04.jpg",
  "./assets/images/waterfront-05.jpg",
  "./assets/images/waterfront-06.jpg",
  "./assets/images/waterfront-07.jpg"
];

let pIdx = 0;
const s1 = document.getElementById('slide1'), s2 = document.getElementById('slide2');
const photoURL = name => new URL(encodeURIComponent(name), document.baseURI).href;
s1.style.backgroundImage = `url("${photoURL(PHOTOS[0])}")`;
s2.style.backgroundImage = `url("${photoURL(PHOTOS[1])}")`;
setInterval(() => {
  pIdx = (pIdx + 1) % PHOTOS.length;
  const active = s1.classList.contains('active') ? s1 : s2;
  const next = active === s1 ? s2 : s1;
  next.style.backgroundImage = `url("${photoURL(PHOTOS[pIdx])}")`;
  active.classList.remove('active');
  next.classList.add('active');
}, 8000);

const ICON_SLUGS={"youtube.com":"youtube","discord.com":"discord","spotify.com":"spotify","twitch.tv":"twitch","reddit.com":"reddit","github.com":"github","drive.google.com":"googledrive","classroom.google.com":"googleclassroom","canva.com":"canva","chatgpt.com":"openai","mail.google.com":"gmail","wikipedia.org":"wikipedia","roblox.com":"roblox","krunker.io":"krunker","1v1.lol":"1v1dotlol","shellshock.io":"egghead","tetr.io":"tetris","chess.com":"chessdotcom","poki.com":"poki","crazygames.com":"crazygames","itch.io":"itchdotio","agar.io":"agar","geoguessr.com":"geoguessr","play2048.co":"2048"};
/* Grids */
function makeDocDropdown(root,options,initial,onChange,kind="catalog"){
 let value=initial;
 const triggerClass=kind==="catalog"?"catalog-dropdown-trigger":"custom-select-trigger";
 const menuClass=kind==="catalog"?"catalog-dropdown-menu":"custom-select-menu";
 const optionClass=kind==="catalog"?"catalog-dropdown-option":"custom-select-option";
 root.innerHTML=`<button type="button" class="${triggerClass}" aria-haspopup="listbox" aria-expanded="false"><span></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button><div class="${menuClass}" role="listbox" hidden></div>`;
 const trigger=root.querySelector("button"),label=trigger.querySelector("span"),menu=root.querySelector('[role="listbox"]');
 function draw(){
  const selected=options.find(o=>o.value===value)||options[0];label.textContent=selected.label;
  menu.innerHTML=options.map(o=>`<button type="button" class="${optionClass}" role="option" data-value="${o.value}" aria-selected="${o.value===value}">${o.label}</button>`).join("");
 }
 function close(){root.classList.remove("open");trigger.setAttribute("aria-expanded","false");menu.hidden=true}
 trigger.addEventListener("click",()=>{const opening=!root.classList.contains("open");document.querySelectorAll(".catalog-dropdown.open,.custom-select.open").forEach(el=>{el.classList.remove("open");el.querySelector("button")?.setAttribute("aria-expanded","false");const m=el.querySelector('[role="listbox"]');if(m)m.hidden=true});if(opening){root.classList.add("open");trigger.setAttribute("aria-expanded","true");menu.hidden=false}});
 menu.addEventListener("click",e=>{const option=e.target.closest("[data-value]");if(!option)return;value=option.dataset.value;draw();close();onChange(value)});
 root._docSelect={get value(){return value},set value(v){if(options.some(o=>o.value===v)){value=v;draw();onChange(value)}}};
 draw();return root._docSelect;
}
document.addEventListener("click",e=>{if(!e.target.closest(".catalog-dropdown,.custom-select"))document.querySelectorAll(".catalog-dropdown.open,.custom-select.open").forEach(el=>{el.classList.remove("open");el.querySelector("button")?.setAttribute("aria-expanded","false");const m=el.querySelector('[role="listbox"]');if(m)m.hidden=true})});
function populateGrid(containerId,list,filterId,categoryId,countId,kind){
 const grid=document.getElementById(containerId),search=document.getElementById(filterId),categoryRoot=document.getElementById(categoryId),count=document.getElementById(countId);
 let categoryValue="all";
 const options=[{value:"all",label:"Every category"},...([...new Set(list.map(x=>x.category))].sort().map(c=>({value:c,label:c})))];
 const category=makeDocDropdown(categoryRoot,options,"all",v=>{categoryValue=v;render()});
 function render(){
  const q=search.value.trim().toLowerCase(),cat=categoryValue;
  const filtered=list.filter(x=>(cat==="all"||x.category===cat)&&[x.name,x.desc,x.category].join(" ").toLowerCase().includes(q));
  count.textContent=filtered.length+" "+(kind==="play"?"experiences":"destinations");
  grid.innerHTML=filtered.length?filtered.map((x,i)=>{const slug=ICON_SLUGS[x.icon]||"",src=slug?"https://cdn.simpleicons.org/"+slug:"https://icons.duckduckgo.com/ip3/"+x.icon+".ico";return `<button class="card catalog-card ${kind}-card" type="button" data-url="${x.url}" style="--card-order:${i}" aria-label="Open ${x.name}"><span class="catalog-icon"><img src="${src}" alt="" loading="lazy" onerror="this.onerror=null;this.src='https://icons.duckduckgo.com/ip3/${x.icon}.ico'"></span><span class="catalog-copy"><span class="catalog-name">${x.name}</span><span class="catalog-desc">${x.desc}</span><span class="catalog-tag">${x.category}</span></span><span class="catalog-arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M7 17 17 7M7 7h10v10"/></svg></span></button>`}).join(""):'<div class="catalog-empty">No matches. Try a different search or category.</div>';
 }
 search.addEventListener("input",render);
 grid.addEventListener("click",e=>{const card=e.target.closest("[data-url]");if(card)launchBrowser(card.dataset.url)});
 render();
}
populateGrid("apps-grid",APPS,"apps-filter","apps-category","apps-count","app");
populateGrid("games-grid",GAMES,"games-filter","games-category","games-count","play");

/* Navigation Views */
const dockItems = document.querySelectorAll('.dock-item');
const viewPanels = document.querySelectorAll('.view-panel');

dockItems.forEach(item => {
  item.addEventListener('click', () => {
    const target = item.dataset.view;
    dockItems.forEach(i => i.classList.remove('active'));
    viewPanels.forEach(p => p.classList.remove('active'));
    item.classList.add('active');
    document.getElementById(`view-${target}`).classList.add('active');
  });
});

/* Search Engine Selector */
const engines = {
  ddg: { name: "DuckDuckGo", url: "https://duckduckgo.com/?q=%s" },
  google: { name: "Google", url: "https://google.com/search?q=%s" },
