let currentEngine = 'ddg';
const engineToggle = document.getElementById('engine-toggle');
const engineMenu = document.getElementById('engine-menu');

engineToggle.addEventListener('click', (e) => { e.stopPropagation(); engineMenu.classList.toggle('open'); });
document.addEventListener('click', () => engineMenu.classList.remove('open'));

document.querySelectorAll('.engine-opt').forEach(opt => {
  opt.addEventListener('click', () => {
    currentEngine = opt.dataset.engine;
    document.getElementById('engine-name').textContent = engines[currentEngine].name;
    engineMenu.classList.remove('open');
  });
});


/* Tab Cloak: changes the browser-tab title and favicon together. */
const TAB_CLOAKS = {
  none: { title: "Doc", icon: null },
  clever: { title: "Clever Portal", icon: "https://www.google.com/s2/favicons?domain=clever.com&sz=64" },
  canvas: { title: "Dashboard", icon: "https://www.google.com/s2/favicons?domain=canvas.instructure.com&sz=64" },
  classroom: { title: "Home - Classroom", icon: "././assets/images/classroom.svg" },
  youtube: { title: "YouTube", icon: "https://www.google.com/s2/favicons?domain=youtube.com&sz=64" },
  drive: { title: "Home - Google Drive", icon: "././assets/images/google-drive.svg" }
};
const cloakRoot = document.getElementById("setting-cloak");
const cloakOptions=[{value:"none",label:"None"},{value:"clever",label:"Clever Portal"},{value:"canvas",label:"Dashboard"},{value:"classroom",label:"Home - Classroom"},{value:"youtube",label:"YouTube"},{value:"drive",label:"Home - Google Drive"}];
let cloakValue="none";
const cloakSelect=makeDocDropdown(cloakRoot,cloakOptions,"none",v=>applyTabCloak(v),"settings");
const cloakIcon = document.getElementById("tab-cloak-icon");
function applyTabCloak(value) {
  const cloak = TAB_CLOAKS[value] || TAB_CLOAKS.none;
  document.title = cloak.title;
  if (cloak.icon) cloakIcon.href = cloak.icon;
  else cloakIcon.href = "data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%230088a8'/%3E%3Ctext x='32' y='44' font-size='42' text-anchor='middle' fill='white' font-family='Arial'%3ED%3C/text%3E%3C/svg%3E";
  try { localStorage.setItem("doc-tab-cloak", value); } catch (e) {}
  /* The JSDelivr SVG runs this page inside an iframe, so mirror the cloak to its real browser tab. */
  try { window.parent.postMessage({type:"doc-tab-cloak",title:cloak.title,icon:cloak.icon||""},"*"); } catch (e) {}
}
try {
  const savedCloak = localStorage.getItem("doc-tab-cloak");
  if (savedCloak && TAB_CLOAKS[savedCloak]) cloakSelect.value = savedCloak;
} catch (e) {}
applyTabCloak(cloakSelect.value);

/* Pro Browsing Session via Scramjet */
const DOC_UPDATE_REPO="theexpie/fuckin-doc-idk";
const DOC_UPDATE_API="https://api.github.com/repos/"+DOC_UPDATE_REPO+"/commits/main";
let docKnownCommit=null,docPendingCommit=null,docUpdateBusy=false;
async function checkForDocUpdate(){
 if(docUpdateBusy||document.visibilityState==="hidden")return;
 docUpdateBusy=true;
 try{
  const response=await fetch(DOC_UPDATE_API,{cache:"no-store",headers:{Accept:"application/vnd.github+json"}});
  if(!response.ok)throw new Error("Update check unavailable");
  const latest=(await response.json())?.sha;
  if(!latest)return;
  if(!docKnownCommit){
   docKnownCommit=latest;
   const pinned=location.pathname.match(/\/gh\/theexpie\/fuckin-doc-idk@([0-9a-f]{40})\//i)?.[1];
   if(pinned&&pinned!==latest)docPendingCommit=latest;
  }else if(latest!==docKnownCommit){
   docKnownCommit=latest;
   docPendingCommit=latest;
  }
  applyDocUpdateIfReady();
 }catch(error){console.debug("[Doc] Update check skipped:",error?.message||error)}
 finally{docUpdateBusy=false}
}
function applyDocUpdateIfReady(){
 if(!docPendingCommit||mainView.classList.contains("active"))return;
 const commit=docPendingCommit;
 docPendingCommit=null;
 console.info("[Doc] Applying update",commit);
 if(location.hostname==="cdn.jsdelivr.net"){
  const next=location.href.replace(/\/gh\/theexpie\/fuckin-doc-idk(?:@[0-9a-f]{40})?\//i,"/gh/theexpie/fuckin-doc-idk@"+commit+"/");
  if(next!==location.href){location.replace(next);return}
 }
 const next=new URL(location.href);
 next.searchParams.set("doc-build",commit);
 location.replace(next.href);
}
setTimeout(checkForDocUpdate,12000);
setInterval(checkForDocUpdate,180000);
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="visible")checkForDocUpdate()});
const mainView = document.getElementById('main-view');
const browserFrame = document.getElementById('browser-frame');
const urlDisplay = document.getElementById('current-url-display');

const startupLoader=document.getElementById("startup-loader");
const pageLoader=document.getElementById("page-loader");
let pageLoadToken=0;
function showPageLoader(){
  const token=++pageLoadToken;
  if(pageLoader){
    pageLoader.hidden=false;
    pageLoader.setAttribute("aria-busy","true");
    requestAnimationFrame(()=>{if(token===pageLoadToken)pageLoader.classList.add("is-visible")});
  }
  return token;
}
function hidePageLoader(token){
  if(token!==undefined&&token!==pageLoadToken)return;
  if(!pageLoader)return;
  pageLoader.classList.remove("is-visible");
  pageLoader.removeAttribute("aria-busy");
  setTimeout(()=>{if(token===undefined||token===pageLoadToken)pageLoader.hidden=true},260);
}
function waitForBrowserFrameLoad(timeout=18000){
  return new Promise(resolve=>{
    let finished=false;
    const finish=()=>{if(finished)return;finished=true;clearTimeout(timer);browserFrame.removeEventListener("load",finish);resolve()};
    browserFrame.addEventListener("load",finish,{once:true});
    const timer=setTimeout(finish,timeout);
  });
}
async function navigateWithLoader(action){
  const token=showPageLoader();
  const started=performance.now();
  const frameReady=waitForBrowserFrameLoad();
  try{
    await Promise.all([Promise.resolve().then(action),frameReady]);
  }finally{
    await new Promise(resolve=>setTimeout(resolve,Math.max(0,520-(performance.now()-started))));
    hidePageLoader(token);
  }
}


const homeDock = document.getElementById('dock');
const dockEdgeTrigger = document.getElementById('dock-edge-trigger');
function syncBrowsingChrome() {
  const browsing = mainView.classList.contains('active');
  document.body.classList.toggle('browsing', browsing);
  if (homeDock) homeDock.style.setProperty('display', browsing ? 'none' : 'flex', 'important');
  if (dockEdgeTrigger) dockEdgeTrigger.style.setProperty('display', browsing ? 'none' : 'block', 'important');
}
new MutationObserver(syncBrowsingChrome).observe(mainView, { attributes: true, attributeFilter: ['class'] });
syncBrowsingChrome();

async function launchBrowser(url) {
  mainView.classList.add('active');
  syncBrowsingChrome();
  let target=/^https?:\/\//i.test(url)?url:'https://'+url;
  urlDisplay.value=target;
  const title=new URL(target).hostname.replace(/^www\./,"");
  if(!activeBrowserTab)createBrowserTab();
  const tab=browserTabs.find(t=>t.id===activeBrowserTab);if(tab){tab.url=target;tab.title=title;renderBrowserTabs()}
  document.getElementById('active-tab-title').textContent=title;
  addHistory(target,title);
  try{await navigateWithLoader(()=>DOC_ENGINE.go(browserFrame,target))}
  catch(e){const box=document.getElementById("console-logs");if(box){const line=document.createElement("div");line.style.color="#fb7185";line.textContent="> "+(e?.message||e);box.appendChild(line)}urlDisplay.value="Proxy error — open DevTools for details";}
}

document.getElementById('search-bar').addEventListener('keydown', (e) => {
  if (e.key === 'Enter') {
    let val = e.target.value.trim();
    if (!val) return;
    let targetUrl = /^https?:\/\//i.test(val) ? val : (val.includes('.') ? 'https://' + val : engines[currentEngine].url.replace('%s', encodeURIComponent(val)));
    launchBrowser(targetUrl);
  }
});

document.getElementById('btn-return').addEventListener('click', () => { mainView.classList.remove('active'); syncBrowsingChrome(); document.getElementById("url-toolbar")?.classList.remove("collapsed"); toolbarCollapsed=false; document.getElementById("tb-collapse").disabled=false; });
mainView.addEventListener("transitionend",applyDocUpdateIfReady);
new MutationObserver(applyDocUpdateIfReady).observe(mainView,{attributes:true,attributeFilter:["class"]});

document.getElementById('tb-back').addEventListener('click',()=>navigateWithLoader(()=>DOC_ENGINE.back(browserFrame)).catch(e=>console.warn("[Doc] Back navigation:",e)));
document.getElementById('tb-forward').addEventListener('click',()=>navigateWithLoader(()=>DOC_ENGINE.forward(browserFrame)).catch(e=>console.warn("[Doc] Forward navigation:",e)));
document.getElementById('tb-refresh').addEventListener('click',()=>navigateWithLoader(()=>DOC_ENGINE.reload(browserFrame)).catch(e=>console.warn("[Doc] Reload:",e)));
DOC_ENGINE.init().catch(error=>{const box=document.getElementById("console-logs");if(box){const line=document.createElement("div");line.style.color="#fb7185";line.textContent="Engine initialization: "+(error?.message||error);box.appendChild(line)}});
function dismissStartupLoader(){if(!startupLoader||startupLoader.dataset.dismissed)return;startupLoader.dataset.dismissed="1";startupLoader.style.opacity="0";startupLoader.style.visibility="hidden";setTimeout(()=>startupLoader.remove(),320)}
if(document.readyState==="complete")requestAnimationFrame(()=>setTimeout(dismissStartupLoader,180));
else window.addEventListener("load",()=>setTimeout(dismissStartupLoader,180),{once:true});
setTimeout(dismissStartupLoader,4500);
/* Sidebar Panels */
const panels = {
  devtools: document.getElementById('panel-devtools'),
  bookmarks: document.getElementById('panel-bookmarks'),
  history: document.getElementById('panel-history')
};
document.getElementById('btn-devtools').addEventListener('click',()=>openBrowserPanel('devtools'));
document.getElementById('btn-bookmarks').addEventListener('click',()=>openBrowserPanel('bookmarks'));
document.querySelectorAll('.panel-close').forEach(btn=>btn.addEventListener('click',()=>panels[btn.dataset.close]?.classList.remove('open')));

let toolbarCollapsed = false;

/* Browser workspace: multi-tab state, persistent history, movable utility panels. */
const browserTabs=[];
let activeBrowserTab=null;
let tabSequence=0;
const historyStore=(()=>{try{return JSON.parse(localStorage.getItem("doc-history")||"[]")}catch{return []}})();
const bookmarkStore=[
 {title:"YouTube",url:"https://www.youtube.com"},
 {title:"Discord",url:"https://discord.com/app"},
 {title:"GitHub",url:"https://github.com"}
];
const tabStrip=document.getElementById("tab-strip");
const browserChrome=document.getElementById("browser-chrome");
const chromeReveal=document.getElementById("chrome-reveal");
function tabTitle(url){try{return new URL(url).hostname.replace(/^www\./,"")}catch{return "New tab"}}
function persistHistory(){try{localStorage.setItem("doc-history",JSON.stringify(historyStore.slice(0,100)))}catch{}}
let tabPointerDrag=null;
function animateTabStrip(mutator){
 const nodes=[...tabStrip.querySelectorAll(".browser-tab,.tab-drop-placeholder")];
 const before=new Map(nodes.map(node=>[node,node.getBoundingClientRect().left]));
 mutator();
 const after=[...tabStrip.querySelectorAll(".browser-tab,.tab-drop-placeholder")];
 after.forEach(node=>{const old=before.get(node);if(old===undefined)return;const dx=old-node.getBoundingClientRect().left;if(Math.abs(dx)<1)return;node.style.transition="none";node.style.transform="translateX("+dx+"px)"});
 tabStrip.getBoundingClientRect();
 requestAnimationFrame(()=>after.forEach(node=>{if(node.isConnected){node.style.transition="";node.style.transform=""}}));
}
function renderBrowserTabs(){
 tabStrip.innerHTML="";
 browserTabs.forEach(tab=>{
  const el=document.createElement("div");el.className="browser-tab"+(tab.id===activeBrowserTab?" active":"");el.dataset.tabId=tab.id;
  const title=document.createElement("span");title.className="tab-title";title.textContent=tab.title||"New tab";
  const close=document.createElement("button");close.className="tab-close";close.type="button";close.setAttribute("aria-label","Close tab");close.textContent="×";
  close.addEventListener("click",e=>{e.stopPropagation();closeBrowserTab(tab.id)});
  el.append(title,close);
  el.addEventListener("pointerdown",e=>{
   if(e.target.closest(".tab-close")||e.button!==0||tabPointerDrag)return;
   e.preventDefault();try{el.setPointerCapture(e.pointerId)}catch{}
   const r=el.getBoundingClientRect();
   tabPointerDrag={id:tab.id,pointerId:e.pointerId,startX:e.clientX,x:e.clientX,grabOffset:e.clientX-r.left,started:false,el,placeholder:null};
  });
  tabStrip.appendChild(el);
 });
}
function beginTabReorder(drag){
 const r=drag.el.getBoundingClientRect(),placeholder=document.createElement("div");
 placeholder.className="tab-drop-placeholder";placeholder.style.width=r.width+"px";placeholder.style.flexBasis=r.width+"px";
 animateTabStrip(()=>tabStrip.insertBefore(placeholder,drag.el));
 drag.el.classList.add("tab-drag-source","tab-drag-ghost");
 Object.assign(drag.el.style,{position:"fixed",left:r.left+"px",top:r.top+"px",width:r.width+"px",height:r.height+"px",margin:"0",flex:"none",zIndex:"2147483647",pointerEvents:"none",transform:"none",transition:"none"});
 document.body.appendChild(drag.el);tabStrip.classList.add("is-reordering");drag.placeholder=placeholder;drag.started=true;
}
function moveTabReorder(e){
 const d=tabPointerDrag;if(!d||d.pointerId!==e.pointerId)return;d.x=e.clientX;
 if(!d.started&&Math.abs(e.clientX-d.startX)>5)beginTabReorder(d);
 if(!d.started)return;e.preventDefault();d.el.style.left=(e.clientX-d.grabOffset)+"px";
 const tabs=[...tabStrip.querySelectorAll(".browser-tab:not(.tab-drag-source)")];let reference=null;
 for(const tab of tabs){const r=tab.getBoundingClientRect();if(e.clientX<r.left+r.width/2){reference=tab;break}}
 if(reference!==d.placeholder.nextElementSibling&&!(reference===null&&d.placeholder.nextElementSibling===null)){
  animateTabStrip(()=>tabStrip.insertBefore(d.placeholder,reference));
 }
 const r=tabStrip.getBoundingClientRect(),edge=30;
 if(e.clientX<r.left+edge)tabStrip.scrollLeft-=Math.max(1,Math.ceil((r.left+edge-e.clientX)*.18));
 else if(e.clientX>r.right-edge)tabStrip.scrollLeft+=Math.max(1,Math.ceil((e.clientX-(r.right-edge))*.18));
}
function finishTabReorder(e){
 const d=tabPointerDrag;if(!d||d.pointerId!==e.pointerId)return;tabPointerDrag=null;
 if(!d.started){switchBrowserTab(d.id);return}
 animateTabStrip(()=>d.placeholder.replaceWith(d.el));
 d.el.classList.remove("tab-drag-source","tab-drag-ghost");
 ["position","left","top","width","height","margin","flex","zIndex","pointerEvents","transform","transition"].forEach(k=>d.el.style[k]="");
 tabStrip.classList.remove("is-reordering");
 const order=[...tabStrip.querySelectorAll(".browser-tab")].map(n=>n.dataset.tabId);
 browserTabs.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));
 tabStrip.querySelector('[data-tab-id="'+d.id+'"]')?.scrollIntoView({block:"nearest",inline:"nearest",behavior:"smooth"});
}
window.addEventListener("pointermove",moveTabReorder,{passive:false});
window.addEventListener("pointerup",finishTabReorder);
window.addEventListener("pointercancel",finishTabReorder);
function createBrowserTab(url=""){
 const tab={id:"tab-"+(++tabSequence),url,title:url?tabTitle(url):"New tab"};browserTabs.push(tab);activeBrowserTab=tab.id;renderBrowserTabs();if(url)navigateBrowserTab(tab,url);return tab;
}
function switchBrowserTab(id){
 const tab=browserTabs.find(t=>t.id===id);if(!tab)return;activeBrowserTab=id;
 if(tab.url){
  urlDisplay.value=tab.url;document.getElementById("active-tab-title").textContent=tab.title;
  navigateWithLoader(()=>DOC_ENGINE.go(browserFrame,tab.url)).catch(e=>console.warn("[Doc] Tab navigation:",e));
 }else{browserFrame.src="about:blank";urlDisplay.value="";hidePageLoader()}
 renderBrowserTabs();
}
function closeBrowserTab(id){
 const i=browserTabs.findIndex(t=>t.id===id);if(i<0)return;browserTabs.splice(i,1);
 if(!browserTabs.length){createBrowserTab();return}
 if(activeBrowserTab===id){const next=browserTabs[Math.max(0,i-1)];switchBrowserTab(next.id)}else renderBrowserTabs();
}
function addHistory(url,title){if(!url)return;historyStore.unshift({url,title:title||tabTitle(url),time:Date.now()});historyStore.splice(100);persistHistory();renderHistory()}
function renderHistory(){
 const list=document.getElementById("history-list");if(!list)return;
 list.innerHTML=historyStore.length?historyStore.map((item,i)=>'<div class="history-entry" data-history-index="'+i+'"><span><strong></strong><small></small></span><small>'+new Date(item.time).toLocaleString()+'</small></div>').join(""):'<div class="history-empty">Pages you visit will show up here.</div>';
 list.querySelectorAll("[data-history-index]").forEach(el=>{const item=historyStore[Number(el.dataset.historyIndex)];el.querySelector("strong").textContent=item.title;el.querySelector("span small").textContent=item.url;el.addEventListener("click",()=>launchBrowser(item.url))});
}
function renderBookmarks(){
 const list=document.getElementById("bookmarks-list");if(!list)return;
 list.innerHTML=bookmarkStore.map((item,i)=>'<div class="bookmark-entry" data-bookmark-index="'+i+'"><span><strong></strong><small></small></span><span aria-hidden="true">↗</span></div>').join("");
 list.querySelectorAll("[data-bookmark-index]").forEach(el=>{const item=bookmarkStore[Number(el.dataset.bookmarkIndex)];el.querySelector("strong").textContent=item.title;el.querySelector("small").textContent=item.url;el.addEventListener("click",()=>launchBrowser(item.url))});
}
function openBrowserPanel(name){
 Object.entries(panels).forEach(([key,panel])=>panel.classList.toggle("open",key===name&&!panel.classList.contains("open")));
 document.getElementById("browser-menu-popover").classList.remove("open");
}
document.getElementById("browser-menu").addEventListener("click",e=>{e.stopPropagation();document.getElementById("browser-menu-popover").classList.toggle("open")});
document.getElementById("browser-menu-popover").addEventListener("click",e=>e.stopPropagation());
document.addEventListener("click",()=>document.getElementById("browser-menu-popover")?.classList.remove("open"));
document.getElementById("btn-history").addEventListener("click",()=>openBrowserPanel("history"));
document.getElementById("new-tab").addEventListener("click",()=>createBrowserTab());
document.getElementById("current-url-display").addEventListener("keydown",e=>{
 if(e.key!=="Enter")return;const raw=e.currentTarget.value.trim();if(!raw)return;
 const target=/^https?:\/\//i.test(raw)?raw:(raw.includes(".")?"https://"+raw:engines[currentEngine].url.replace("%s",encodeURIComponent(raw)));
 launchBrowser(target);e.currentTarget.blur();
});
document.getElementById("tb-collapse").addEventListener("click",()=>{browserChrome.classList.add("collapsed");chromeReveal.classList.add("visible")});
chromeReveal.addEventListener("click",()=>{browserChrome.classList.remove("collapsed");chromeReveal.classList.remove("visible")});
document.getElementById("btn-return").addEventListener("click",()=>{document.body.classList.remove("browsing");mainView.classList.remove("active");browserChrome.classList.remove("collapsed");chromeReveal.classList.remove("visible");document.getElementById("url-toolbar")?.classList.remove("collapsed");toolbarCollapsed=false;document.getElementById("tb-collapse").disabled=false;});
function makePanelMovable(panel){
 const handle=panel.querySelector(".drag-handle");if(!handle)return;let drag=null;
 handle.addEventListener("pointerdown",e=>{if(e.target.closest("button"))return;const r=panel.getBoundingClientRect();drag={x:e.clientX-r.left,y:e.clientY-r.top};handle.setPointerCapture(e.pointerId)});
 handle.addEventListener("pointermove",e=>{if(!drag)return;const x=Math.max(0,Math.min(innerWidth-panel.offsetWidth,e.clientX-drag.x));const y=Math.max(0,Math.min(innerHeight-panel.offsetHeight,e.clientY-drag.y));panel.style.left=x+"px";panel.style.top=y+"px";panel.style.right="auto"});
 const stop=()=>drag=null;handle.addEventListener("pointerup",stop);handle.addEventListener("pointercancel",stop);
}
Object.values(panels).forEach(makePanelMovable);
renderBookmarks();renderHistory();
createBrowserTab();

/* Dock visibility is synchronized to the actual browser-view state above. */
</script>
</body>
</html>
