const frame=document.createElementNS("http://www.w3.org/1999/xhtml","iframe");
frame.setAttribute("title","Doc browser");
frame.setAttribute("allow","clipboard-read; clipboard-write; fullscreen; autoplay; picture-in-picture");
frame.style.cssText="position:fixed;inset:0;width:100%;height:100%;border:0;display:block;background:#061d25";
document.documentElement.style.cssText="width:100%;height:100%;margin:0;overflow:hidden;background:#061d25";
document.body && (document.body.style.cssText="margin:0;width:100%;height:100%;overflow:hidden");
/* Keep the application assembled inside the SVG entrypoint for JSDelivr. */
frame.srcdoc=page.replace("__DOC_BASE__",base);
/* Relay iframe tab-cloak settings to the actual top-level SVG document. */
window.addEventListener("message",function(event){
  if(event.source!==frame.contentWindow||!event.data||event.data.type!=="doc-tab-cloak")return;
  const title=String(event.data.title||"Doc").slice(0,120);
  document.title=title;
  let icon=document.querySelector('link[rel~="icon"]');
  if(!icon){icon=document.createElementNS("http://www.w3.org/1999/xhtml","link");icon.setAttribute("rel","icon");document.head.appendChild(icon)}
  const iconPath=String(event.data.icon||"");
  icon.setAttribute("href",iconPath?new URL(iconPath,base).href:"data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' rx='16' fill='%230088a8'/%3E%3Ctext x='32' y='44' font-size='42' text-anchor='middle' fill='white' font-family='Arial'%3ED%3C/text%3E%3C/svg%3E");
});
const host=document.createElementNS("http://www.w3.org/2000/svg","foreignObject");host.setAttribute("x","0");host.setAttribute("y","0");host.setAttribute("width","100%");host.setAttribute("height","100%");host.appendChild(frame);document.documentElement.appendChild(host);
})();
